@push('scripts')
<script>
(() => {
    let variantIndex = {{ $editing ? $product->variants->count() : 0 }};
    let specIndex = {{ $editing ? $product->specifications->count() : 0 }};
    const table = document.querySelector('#variants-table tbody');
    document.querySelector('#add-variant').addEventListener('click', () => {
        const i = variantIndex++;
        table.insertAdjacentHTML('beforeend', `<tr><td><input name="variants[${i}][name]" class="form-control form-control-sm" required></td><td><input name="variants[${i}][sku]" class="form-control form-control-sm" required></td><td><input name="variants[${i}][price]" type="number" step="0.01" class="form-control form-control-sm" required></td><td><input name="variants[${i}][mrp]" type="number" step="0.01" class="form-control form-control-sm"></td><td><input name="variants[${i}][stock_quantity]" type="number" min="0" class="form-control form-control-sm" required></td><td><input name="variants[${i}][color]" class="form-control form-control-sm"></td><td><button type="button" class="btn btn-sm btn-link text-danger remove-variant"><i class="fas fa-times"></i></button></td></tr>`);
    });
    document.addEventListener('click', event => { if (event.target.closest('.remove-variant,.remove-row')) event.target.closest('tr,.spec-row').remove(); });
    document.querySelector('#add-spec').addEventListener('click', () => { const i = specIndex++; document.querySelector('#specifications').insertAdjacentHTML('beforeend', `<div class="row g-2 mb-2 spec-row"><div class="col-5"><input name="specification_name[${i}]" class="form-control" placeholder="Attribute"></div><div class="col-6"><input name="specification_value[${i}]" class="form-control" placeholder="Value"></div><div class="col-1"><button type="button" class="btn btn-link text-danger remove-row"><i class="fas fa-times"></i></button></div></div>`); });
    const price = document.querySelector('#price'), mrp = document.querySelector('#mrp');
    document.querySelector('#add-youtube').addEventListener('click', () => { document.querySelector('#youtube-fields').insertAdjacentHTML('beforeend', '<input name="youtube_urls[]" class="form-control mb-2" placeholder="https://www.youtube.com/watch?v=...">'); });
    const updatePreview = () => { const selling = parseFloat(price.value) || 0, marked = parseFloat(mrp.value) || 0, discount = marked > selling ? ((marked-selling)/marked*100) : 0; document.querySelector('#preview-price').textContent = `Rs. ${selling.toFixed(2)}`; document.querySelector('#preview-mrp').textContent = `Rs. ${marked.toFixed(2)}`; document.querySelector('#preview-discount').textContent = `${discount.toFixed(0)}% OFF`; };
    price.addEventListener('input', updatePreview); mrp.addEventListener('input', updatePreview); updatePreview();
})();
</script>
